#!/usr/bin/env bash
# СУДИТ: hooks/root-cause-lib.sh hooks/five-whys-gate.sh scripts/outcome.sh
# probe_D1129 — повод переработки файла с «\» в имени не снимается старым пунктом о другом файле. Красная (1), пока
# `awk -v` раскрывает экранирование в токене, контекст повода пуст, и сверка без контекста судит только форму —
# снятие «открыто при отказе» (третий скептик, L1). Положительный контроль — с обычным именем отказ остаётся. Рамка — 2.
. "$(dirname "$0")/outcome_frame_lib.sh" || exit 2
run() {   # <sid> <имя файла переработки> → решение стража после исхода старым пунктом о другом файле
    P="$SB/p-$1"; gproj "$P" || return 2
    F="$P/hooks/$2"; seq 1 20 > "$F"
    item "$P/BACKLOG.md" D9800 "hooks/y.sh:4"
    ( cd "$P" && git add -A && git -c user.email=t@t -c user.name=t commit -qm old ) || return 2
    jq -cn --arg p "$F" '{ts:"2026-10-26T09:00:00Z",path:$p,cycles:2}' > "$ST/rework-fired-$1.jsonl"
    jq -cn --arg p "$F" '{ts:"2026-10-26T09:01:00Z",path:$p,cycles:3}' >> "$ST/rework-fired-$1.jsonl"
    TR="$SB/tr-$1.jsonl"; mk_tr "$TR" "Правлю файл дальше."
    # Страж исполняется из каталога проекта, как в мире: адрес старого пункта тогда разрешается, и сверка одной формы
    # его принимает (из чужого каталога адрес не разрешается, и обход не виден — так проба была зелёной на дефекте).
    [ "$(cd "$P" && dec "$(cw "$1" "$F" "$TR" "$P")")" = deny ] || return 2
    no "$1" debt rework D9800 "$P"
    ( cd "$P" && dec "$(cw "$1" "$F" "$TR" "$P")" )
}
[ "$(run s1 'ab.sh')" = deny ] || exit 2
[ "$(run s2 'a\tb.sh')" = deny ] || { echo "старый пункт о другом файле снял повод «a\\tb.sh»" >&2; exit 1; }
# Значение токена доходит до чтения журнала без раскрытия экранирования: первый взгляд на повод записан один раз, а не на
# каждом вызове стража (иначе и снимок брался бы заново).
[ "$(grep -c '^seen-at|rework:' "$ST/five-whys-s2.seen" 2>/dev/null)" = 1 ] || { echo "первый взгляд на повод «a\\tb.sh» записан не один раз" >&2; exit 1; }
echo "экранирование в токене не открывает снятие"
exit 0
